#!/usr/bin/env python3
"""Run C1 Unit04 recalibration with narrow depth extensions that avoid new target forms."""
from pathlib import Path
SOURCE=Path(__file__).with_name('recalibrate_final_arabic_c1_unit04.py')
text=SOURCE.read_text(encoding='utf-8')
patches={
"قالت ريم إن التصنيف مفيد عندما يضغط كمية كبيرة من الملاحظات إلى نمط يمكن مناقشته، لكنه يصبح خطيرًا عندما ننسى أن الحدود صُنعت لأغراض التحليل ويمكن تعديلها إذا قاومتها البيانات.''',":"قالت ريم إن التصنيف مفيد عندما يضغط كمية كبيرة من الملاحظات إلى نمط يمكن مناقشته، لكنه يصبح خطيرًا عندما ننسى أن الحدود صُنعت لأغراض التحليل ويمكن تعديلها إذا قاومتها البيانات. وفي مراجعة أخيرة طلبت من باحث لم يشارك في بناء الفئات أن يعيد تصنيف عينة صغيرة من الأمثلة من دون رؤية الأسماء السابقة. اتفق مع الفريق في بعض المواضع واختلف في أخرى، فاستعملوا الاختلاف لتحديد الحالات الحدية بدل إخفائها. ثم كتبوا قاعدة توضح متى يكون الاسم اختصارًا مريحًا ومتى يحتاج القارئ إلى رؤية الأمثلة التي تقع على الحدود. بذلك أصبح التصنيف قابلًا لإعادة الفحص من شخص آخر، لا قرارًا مغلقًا يورث تفسيره تلقائيًا إلى كل تحليل لاحق.''',",
"قالت سمر إن السياسة الجيدة لا تحتفل بالاختلاف لمجرد وجوده ولا تحاربه لمجرد أنه مختلف، بل تسأل أي وظيفة يؤديها، ومن يستطيع فهمه، وما الدعم الذي يجعل الانتقال بين السياقات قابلًا للتعلم.''',":"قالت سمر إن السياسة الجيدة لا تحتفل بالاختلاف لمجرد وجوده ولا تحاربه لمجرد أنه مختلف، بل تسأل أي وظيفة يؤديها، ومن يستطيع فهمه، وما الدعم الذي يجعل الانتقال بين السياقات قابلًا للتعلم. كما راقب المركز أثر السياسة في المتعلمين الجدد بعد شهرين، لا في المشاركين المعتادين فقط. وجد أن الشرح الصريح للمقام يساعد حين يأتي قبل التعرض مباشرة، بينما تصبح الملاحظات العامة أقل فائدة إذا انفصلت عن مثال حي. لذلك ربط المدرسون كل تغير في الأسلوب بموقف محدد وسألوا الطلاب كيف سيتغير الاختيار لو تغير الجمهور أو الغرض. جعل ذلك الفروق مادة للتحليل والممارسة بدل أن تبقى خلفية اجتماعية غير مشروحة.''',",
"في التقرير الجديد وضع الفريق خريطة تغطية بجانب النتائج حتى يستطيع القارئ رؤية أين توجد الأدلة الكثيفة وأين تبقى الاستنتاجات أكثر هشاشة.''',":"في التقرير الجديد وضع الفريق خريطة تغطية بجانب النتائج حتى يستطيع القارئ رؤية أين توجد الأدلة الكثيفة وأين تبقى الاستنتاجات أكثر هشاشة. ثم أجروا اختبارًا إضافيًا بحذف أكبر مجموعة من التسجيلات وإعادة الحساب. إذا تغيرت النتيجة جذريًا، فهذا يعني أن الاستنتاج يعتمد بشدة على بيئة واحدة حتى لو كان العدد الكلي كبيرًا. بقيت بعض العلاقات مستقرة، بينما ضعفت أخرى، فاستعملوا هذا الفرق لتعديل لغة التقرير. كما نشروا قائمة بالفراغات التي ينبغي أن تستهدفها الجولة التالية من الجمع بدل إضافة تسجيلات جديدة حيث لديهم وفرة بالفعل.''',",
"يستطيع المشروع أن يقدم نصًا مريحًا للقراءة وأن يحتفظ بطريق واضح إلى المادة الأصلية، بحيث يعرف كل قارئ مقدار المسافة بين ما قيل وما يراه مطبوعًا.''',":"يستطيع المشروع أن يقدم نصًا مريحًا للقراءة وأن يحتفظ بطريق واضح إلى المادة الأصلية، بحيث يعرف كل قارئ مقدار المسافة بين ما قيل وما يراه مطبوعًا. وأجرى الفريق مراجعة بين محررين مستقلين على مقطع واحد، فوجد أن بعض قرارات الترقيم والحذف تختلف حتى مع اتباع التعليمات نفسها. لم يعد الاختلاف خطأ شخصيًا فقط، بل معلومة عن المواضع التي تحتاج القاعدة فيها إلى أمثلة أو توضيح أكبر. سجلوا هذه المواضع في دليل التحرير وأبقوا النسخ الوسيطة محفوظة، حتى يستطيع الباحث معرفة كيف انتقل النص من التسجيل إلى الشكل المنشور خطوة بخطوة.''',",
"عندما تكون التحولات قابلة للرؤية والرجوع، يستطيع جمهور اليوم قراءة المضمون، ويستطيع الباحث أيضًا استعادة الأدلة التي يحتاجها لسؤال مختلف.''',":"عندما تكون التحولات قابلة للرؤية والرجوع، يستطيع جمهور اليوم قراءة المضمون، ويستطيع الباحث أيضًا استعادة الأدلة التي يحتاجها لسؤال مختلف. ثم اختبر الناشر السياسة مع قارئين لهما غرضان مختلفان: أحدهما يريد متابعة المضمون بسرعة، والآخر يقارن خصائص الكتابة عبر الفترات. استطاع الأول استخدام النسخة الميسرة، بينما احتاج الثاني إلى الأصل وسجل التغييرات. كشف الاختبار أن الإصدار الجيد لا يحتاج إلى اختيار جمهور واحد وإهمال الآخر إذا أمكن فصل طبقات العرض. كما جعلوا أي تغيير جديد في القواعد يحمل رقم إصدار وتاريخًا حتى لا تختلط الاقتباسات بين نسخ حررت وفق سياسات مختلفة.''',",
"أقوى تحليل يوضح أين دخل اختيار الباحث وأين ظهر اختيار المتحدث وأين غير الوسيط شكل ما وصل إلى القارئ.''',":"أقوى تحليل يوضح أين دخل اختيار الباحث وأين ظهر اختيار المتحدث وأين غير الوسيط شكل ما وصل إلى القارئ. وفي النهاية طلبت ريم من الفريق أخذ نتيجة واحدة ومحاولة تتبعها إلى مصدرها الكامل: التسجيل أو الوثيقة، وظروف الجمع، وخيارات التفريغ، وقرار التصنيف، والصياغة النهائية. كلما تعذر تتبع خطوة أضافوا معلومة إلى السجل. لم تجعل هذه العملية النص النهائي أطول بالضرورة، لكنها جعلت الادعاء قابلًا للتدقيق. كما كشفت أن بعض النتائج تحتاج إلى صياغة أضيق لا لأن البيانات قليلة، بل لأن سلسلة التحويل تحتوي على قرار لا يمكن فصله عن التفسير نفسه.''',",
}
for old,new in patches.items():
    assert text.count(old)==1, f'expected one retry insertion point: {old[:40]!r}'
    text=text.replace(old,new)
exec(compile(text,str(SOURCE),'exec'),{'__name__':'__main__','__file__':str(SOURCE)})
